const config = $('Host configuration').first().json;
const body = await this.helpers.getBinaryDataBuffer(0, 'data');
const envelope = JSON.parse(body.toString('utf8'));
if (envelope.status !== 'ok' || !Array.isArray(envelope.data)) throw new Error('Expected claim envelope');
const unique = new Map();
for (const event of envelope.data) {
 const expiry = typeof event.delivery?.lease_expires_at === 'string' ? Date.parse(event.delivery.lease_expires_at) : NaN;
 if (!/^[0-9a-f]{64}$/.test(event.event_id) || event.delivery.state !== 'delivered' || event.delivery.consumer_id !== config.consumer_id || !Number.isFinite(expiry) || expiry <= Date.now()) throw new Error('Invalid or expired claim');
 unique.set(event.event_id, {json: {event, config, idempotency_key: event.event_id}});
}
return [...unique.values()];

// Replace this node with an explicitly configured host action adapter.
// Persist event_id atomically with the action: retries must return prior success.
// Output event_id, consumer_id, config and host_action_succeeded=true only after success.
throw new Error('Configure host action and durable event_id idempotency before acknowledging');

return $input.all().map(({json: result}) => {
 if (result.host_action_succeeded !== true || !/^[0-9a-f]{64}$/.test(result.event_id) || result.consumer_id !== result.config.consumer_id) throw new Error('Confirmed host action required before ack');
 return {json: {event_id: result.event_id, ack_required: true, argv: [result.config.python_executable, result.config.workflow_cli, 'events', 'ack', result.event_id, '--consumer-id', result.consumer_id, '--store', result.config.events_root, '--json']}};
});
